/*
 * Icon key -> FontAwesome glyph, for controls configured in Headwaters.
 *
 * GENERATED by GUI/tmp/light_icons.py from Headwaters'
 * containers/frontend/public/js/components/fireside-icons.js -- do not edit
 * by hand. Regenerate when that file changes.
 *
 * A control arrives as { id, name, icon } where `icon` is a key, so the
 * dial has to resolve it the same way the PWA does or the user picks one
 * icon and sees another. Legacy keys are folded in for the same reason
 * LEGACY_KEY_MAP exists upstream: a value stored under an old name must
 * still render.
 *
 * Every codepoint here is inside the project's FontAwesome subset; a
 * codepoint outside it draws an empty box and warns about nothing.
 * gen_eez_project.py enforces that.
 */
