/** Resolve an icon key to a glyph, falling back to the bulb like the PWA. */
static inline const char *ui_light_icon(const char *key)
{
    if (!key || !key[0]) {
        return UI_LIGHT_ICON_FALLBACK;
    }
    for (size_t i = 0; i < sizeof(UI_LIGHT_ICONS) / sizeof(*UI_LIGHT_ICONS); i++) {
        if (strcmp(UI_LIGHT_ICONS[i].key, key) == 0) {
            return UI_LIGHT_ICONS[i].glyph;
        }
    }
    return UI_LIGHT_ICON_FALLBACK;
}
